#if UNITY_EDITOR
using System;
using System.Linq;
using System.Reflection;
using LastRail.Battle;
using Newtonsoft.Json.Linq;
using NUnit.Framework;
namespace LastRail.Tests.EditMode {
 public sealed class BEnemyBasicTimingTests {
  internal static BDirectAttackBasicLoopBinding Binding(JObject packet=null){var t=typeof(BDirectAttackBasicLoopTests);var b=t.GetMethod("Binding",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{packet,"BCB01",5,"ENEMY"});return (BDirectAttackBasicLoopBinding)t.GetMethod("LoopBinding",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{b,true,false});}
  internal static JObject Timing(BDirectAttackBasicLoopBinding b,long targetable=600)=>new JObject{["version"]="unity.combat-b.enemy-basic-timing-local.v1",["provenance"]="EXPLICIT_LOCAL_TIMING_NOT_OPERATING_ENEMY_SOURCE",["bindingHash"]=b.OriginalHash,["timings"]=new JArray(new JObject{["sourceId"]="enemy",["targetId"]="car0",["targetableAt"]=targetable,["periodMicroseconds"]=2200000,["windupMs"]=500,["recoveryMs"]=300})};
  static object Invoke(object target,string method,params object[] args){var type=target as Type??target.GetType();var m=type.GetMethod(method);Assert.NotNull(m,"Missing existing-clock enemy timing connection: "+method);try{return m.Invoke(target is Type?null:target,args);}catch(TargetInvocationException e){System.Runtime.ExceptionServices.ExceptionDispatchInfo.Capture(e.InnerException).Throw();throw;}}
  internal static BDirectAttackBasicLoop Fresh(BDirectAttackBasicLoopBinding b=null,int capacity=10000){b=b??Binding();var p=Timing(b);return (BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),"CreateEnemyTimingValidation",b,p,BDirectAttackInput.Digest(p),capacity);}
  static JObject Enemy(BDirectAttackBasicLoop s)=>(JObject)s.Capture()["enemyTiming"]["actors"][0];
  static void Advance(BDirectAttackBasicLoop s,int ticks,string id)=>s.Advance(id,10000L*ticks,ticks);
  [Test] public void FirstImpactWaitsWholePeriodAfterTargetableAndWindupStartsFiveHundredBefore(){var s=Fresh();Advance(s,2299,"before-windup");Assert.AreEqual("IDLE",(string)Enemy(s)["phase"]);Assert.AreEqual(1000,s.Hp("car0"));Advance(s,1,"windup");Assert.AreEqual("WINDUP",(string)Enemy(s)["phase"]);Advance(s,499,"before-impact");Assert.AreEqual(1000,s.Hp("car0"));var r=s.Advance("impact",10000,1);Assert.AreEqual(2800,s.Tick);Assert.AreEqual(1,r.Hits.Count(h=>h.Attack.SourceId=="enemy"));Assert.AreEqual("RECOVERY",(string)Enemy(s)["phase"]);Assert.AreEqual(964,s.Hp("car0"));Advance(s,299,"before-recovery-end");Assert.AreEqual("RECOVERY",(string)Enemy(s)["phase"]);Advance(s,1,"recovery-end");Assert.AreEqual("IDLE",(string)Enemy(s)["phase"]);}
  [Test] public void ExternalRecoveryEndSkipsMissedBasicAndWaitsWholePeriod(){var s=Fresh();Advance(s,2300,"windup");Invoke(s,"RecordEnemyRecoveryEnd","occupied","enemy",5000L);Advance(s,4899,"before-next");Assert.AreEqual(1000,s.Hp("car0"));Advance(s,1,"next-impact");Assert.AreEqual(964,s.Hp("car0"));Assert.AreEqual(7200,s.Tick);}
  [Test] public void SplitPauseDebtAndRestoreUseSameOriginalClock(){var a=Fresh();var b=Fresh();a.SetSpeed("speed",3);b.SetSpeed("speed",3);a.Advance("odd",1,0);b.Advance("odd",1,0);a.SetPaused("pause",true);b.SetPaused("pause",true);Advance(a,100,"paused");Advance(b,100,"paused");a.SetPaused("resume",false);b.SetPaused("resume",false);a.Advance("whole",20000000,3000);for(int n=0;n<20;n++)b.Advance("part"+n,1000000,150);Assert.AreEqual(a.Tick,b.Tick);Assert.AreEqual(a.Hp("car0"),b.Hp("car0"));Assert.IsTrue(JToken.DeepEquals(a.Capture()["enemyTiming"],b.Capture()["enemyTiming"]));var binding=Binding();var p=Timing(binding);var cache=a.Capture();var restored=(BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),"RestoreEnemyTimingValidation",cache,binding,p,BDirectAttackInput.Digest(p),10000);Assert.IsTrue(JToken.DeepEquals(cache,restored.Capture()));Advance(a,100,"tail");Advance(restored,100,"tail");Assert.IsTrue(JToken.DeepEquals(a.Capture(),restored.Capture()));}
  [Test] public void TerminalClearsEnemyReservationsWithoutLateDamage(){var s=Fresh();for(int i=0;i<4&&s.Outcome=="RUNNING";i++)Advance(s,8000,"run-"+i);Assert.AreEqual("VICTORY",s.Outcome);Assert.AreEqual("TERMINAL",(string)Enemy(s)["phase"]);Assert.AreEqual(0,(long)Enemy(s)["reservationSequence"]);int hp=s.Hp("car0");Advance(s,1000,"after-terminal");Assert.AreEqual(hp,s.Hp("car0"));}
  [TestCase(2299)][TestCase(2300)][TestCase(2799)][TestCase(2800)][TestCase(3099)][TestCase(3100)]
  public void RestoreAtEveryActionBoundaryKeepsLaterNativeReceipts(int tick){var b=Binding();var p=Timing(b);var s=Fresh(b);Advance(s,tick,"boundary");var cache=s.Capture();var restored=(BDirectAttackBasicLoop)Invoke(typeof(BDirectAttackBasicLoop),"RestoreEnemyTimingValidation",cache,b,p,BDirectAttackInput.Digest(p),10000);Advance(s,4000,"tail");Advance(restored,4000,"tail");Assert.IsTrue(JToken.DeepEquals(s.Capture(),restored.Capture()));}
  [Test] public void DuplicateOccupationDoesNotRescheduleAndChangedBodyIsRejected(){var s=Fresh();var result=(BDirectAttackBasicLoopResult)Invoke(s,"RecordEnemyRecoveryEnd","occupation","enemy",5000L);var before=s.Capture();Assert.AreSame(result,Invoke(s,"RecordEnemyRecoveryEnd","occupation","enemy",5000L));Assert.Throws<ArgumentException>(()=>Invoke(s,"RecordEnemyRecoveryEnd","occupation","enemy",5001L));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [TestCase(-1L)][TestCase(9007199254740991L)]
  public void InvalidOrOverflowOccupationCannotPublishAnyClockHpOrPhase(long until){var s=Fresh();var before=s.Capture();Assert.Throws<ArgumentException>(()=>Invoke(s,"RecordEnemyRecoveryEnd","invalid","enemy",until));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [Test] public void NativeJournalCapacityFailureAfterStagingPhasePreservesTimingAndNext(){var s=Fresh(capacity:2);s.SetPaused("pause",true);var before=s.Capture();Assert.Throws<InvalidOperationException>(()=>Invoke(s,"RecordEnemyRecoveryEnd","occupation","enemy",5000L));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  [TestCase("enemyTiming")][TestCase("state")][TestCase("results")]
  public void RestoreRejectsTamperingAcrossNativeAndTimingOwners(string key){var b=Binding();var p=Timing(b);var s=Fresh(b);Advance(s,2300,"windup");var before=s.Capture();var bad=(JObject)before.DeepClone();if(key=="results")bad[key][0]["tick"]=1;else bad[key]["unknown"]=1;Assert.Throws<ArgumentException>(()=>Invoke(typeof(BDirectAttackBasicLoop),"RestoreEnemyTimingValidation",bad,b,p,BDirectAttackInput.Digest(p),10000));Assert.IsTrue(JToken.DeepEquals(before,s.Capture()));}
  static JObject OriginalPacket()=>(JObject)typeof(BDirectAttackBasicLoopTests).GetMethod("Packet",BindingFlags.Static|BindingFlags.NonPublic).Invoke(null,new object[]{1});
  [Test] public void ExpiredOriginalGeometryLosesFixedImpactWithoutRetargeting(){var input=OriginalPacket();var g=((JArray)input["geometry"]).Single(r=>(string)r["sourceId"]=="enemy"&&(string)r["targetId"]=="car0");g["validUntilTick"]=2700;var s=Fresh(Binding(input));Advance(s,2800,"invalid-impact");Assert.AreEqual(1000,s.Hp("car0"));Assert.AreEqual(1520,s.Hp("op_mira"));Assert.AreEqual(5000,s.Hp("train"));Assert.IsTrue(((JArray)s.Capture()["enemyTiming"]["events"]).Any(e=>(string)e["kind"]=="MISS_TARGET_INVALID"));Assert.AreEqual("RECOVERY",(string)Enemy(s)["phase"]);}
  [Test] public void ExistingStepRoundingKeepsImpactPeriodWithoutAddingWindupOrRecoveryAgain(){var input=OriginalPacket();input["stepTimeSpanTicks"]=300000;var b=Binding(input);var p=Timing(b,0);var s=BDirectAttackBasicLoop.CreateEnemyTimingValidation(b,p,BDirectAttackInput.Digest(p),10000);s.Advance("pre",56*300000L,56);Assert.AreEqual("IDLE",(string)Enemy(s)["phase"]);s.Advance("windup",300000,1);Assert.AreEqual(57,s.Tick);Assert.AreEqual("WINDUP",(string)Enemy(s)["phase"]);s.Advance("first",17*300000L,17);Assert.AreEqual(74,s.Tick);Assert.AreEqual(964,s.Hp("car0"));s.Advance("second",74*300000L,74);Assert.AreEqual(148,s.Tick);Assert.AreEqual(928,s.Hp("car0"));}
  [TestCase("windupMs")][TestCase("recoveryMs")][TestCase("periodMicroseconds")]
  public void RehashedInputCannotChangeApprovedTimingsOrOriginalPeriod(string field){var b=Binding();var p=Timing(b);p["timings"][0][field]=1;Assert.Throws<ArgumentException>(()=>BDirectAttackBasicLoop.CreateEnemyTimingValidation(b,p,BDirectAttackInput.Digest(p),10000));}
  [Test] public void CoarseStepRecoveryBoundaryStartsNextWindupBeforeItsImpact(){
   // Explicit arithmetic-boundary trial, not a Scout source or new operating enemy profile.
   var input=OriginalPacket();input["stepTimeSpanTicks"]=10000000;((JArray)input["entities"]).Single(e=>(string)e["id"]=="enemy")["basicIntervalMicroseconds"]=1600000;
   var b=Binding(input);var p=Timing(b,0);p["timings"][0]["periodMicroseconds"]=1600000;var s=BDirectAttackBasicLoop.CreateEnemyTimingValidation(b,p,BDirectAttackInput.Digest(p),10000);
   s.Advance("first",20000000,2);Assert.AreEqual("RECOVERY",(string)Enemy(s)["phase"]);Assert.AreEqual(964,s.Hp("car0"));s.Advance("recovery-boundary",10000000,1);Assert.AreEqual("WINDUP",(string)Enemy(s)["phase"]);Assert.AreEqual(4,(long)Enemy(s)["due"]);Assert.AreEqual(964,s.Hp("car0"));s.Advance("second",10000000,1);Assert.AreEqual(928,s.Hp("car0"));
  }
 }
}
#endif
